css:
@import url("https://fonts.googleapis.com/css2?family=Merriweather:wght@400;700&family=Merriweather+Sans:wght@400;600;700&display=swap");
:root{--pn:#1F5C4A;--pn2:#2A7560;--ww:#FBFAF7;--sb:#D7E6F2;--rd:#C8342B;--ink:#1D2A26;--gr:#56645F;--ln:#E3E6E1;--h:"Merriweather",Georgia,serif;--b:"Merriweather Sans",system-ui,sans-serif}
*,*::before,*::after{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;font-family:var(--b);font-size:17px;line-height:1.65;color:var(--ink);background:var(--ww)}
img{max-width:100%;height:auto;display:block}a{color:inherit}h1,h2,h3{font-family:var(--h);font-weight:700;margin:0;line-height:1.2}
.wrap{max-width:1180px;margin:0 auto;padding:0 22px}.skip{position:absolute;left:-999px}.skip:focus{left:10px;top:10px;background:var(--pn);color:#fff;padding:8px;z-index:99}
:focus-visible{outline:3px solid #E0A526;outline-offset:2px}
.urg{background:var(--rd);color:#fff;font-size:15px}.urg .wrap{padding-top:8px;padding-bottom:8px}.urg a{font-weight:700;color:#fff}
.nav{display:flex;justify-content:space-between;align-items:center;height:80px;position:relative;border-bottom:1px solid var(--ln)}
.logo{font-family:var(--h);font-weight:700;font-size:22px;text-decoration:none;color:var(--pn);display:flex;gap:10px;align-items:center}
.menu{display:flex;gap:26px;list-style:none;margin:0;padding:0;font-weight:600;font-size:16px}.menu a{text-decoration:none}.menu a:hover{color:var(--pn2);text-decoration:underline}
.burger{display:none;background:none;border:2px solid var(--pn);color:var(--pn);width:44px;height:40px;border-radius:8px;font-size:20px;cursor:pointer}
.hero{padding:56px 0 70px}.hero .wrap{display:grid;grid-template-columns:1.1fr .9fr;gap:50px;align-items:start}
.hero h1{font-size:clamp(34px,4.4vw,54px);color:var(--pn)}.hero .lead{font-size:19px;color:var(--gr);margin:18px 0 26px;max-width:32em}
.quick{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}
.qt{background:#fff;border:1px solid var(--ln);border-radius:14px;padding:18px;text-decoration:none;display:flex;flex-direction:column;gap:8px}.qt:hover{border-color:var(--pn)}
.qt b{font-size:17px}.qt span{font-size:14px;color:var(--gr)}.qt svg{flex:none}
.card{background:#fff;border:1px solid var(--ln);border-radius:18px;overflow:hidden}.card img{width:100%;aspect-ratio:16/10;object-fit:cover}
.st{padding:20px 22px}.st .now{display:flex;align-items:center;gap:10px;font-weight:700;font-size:19px}.st .dot{width:14px;height:14px;border-radius:50%;background:#2E9E5B;box-shadow:0 0 0 5px rgba(46,158,91,.18)}.st .dot.cl{background:var(--rd);box-shadow:0 0 0 5px rgba(200,52,43,.15)}
.st p{margin:6px 0 0;color:var(--gr);font-size:15px}
section{padding:80px 0}.sh{max-width:640px;margin-bottom:32px}.sh h2{font-size:clamp(28px,3.4vw,40px);color:var(--pn)}.sh p{color:var(--gr);margin:10px 0 0}
.svc{background:#fff;border-top:1px solid var(--ln);border-bottom:1px solid var(--ln)}
.sv{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0}
.s{padding:22px 24px 22px 0;border-bottom:1px solid var(--ln);margin-right:24px}.s h3{font-size:19px;display:flex;align-items:center;gap:10px}.s p{margin:6px 0 0;color:var(--gr);font-size:16px}
.s svg{flex:none}
.chips{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:24px}.chips button{font:600 15px var(--b);background:#fff;border:1px solid #C9D0CB;border-radius:30px;padding:8px 16px;cursor:pointer;color:var(--ink)}.chips button[aria-pressed=true]{background:var(--pn);color:#fff;border-color:var(--pn)}
.docs{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:18px}
.dc{background:#fff;border:1px solid var(--ln);border-radius:16px;overflow:hidden;display:flex;flex-direction:column}.dc img{width:100%;aspect-ratio:1/1;object-fit:cover;object-position:top}
.dc .c{padding:16px 18px 18px;display:flex;flex-direction:column;flex:1}.dc h3{font-size:18px}.dc .sp{color:var(--pn2);font-weight:700;font-size:14px;margin:4px 0 8px}.dc p{margin:0 0 12px;font-size:15px;color:var(--gr);flex:1}
.dc button{font:700 15px var(--b);background:var(--sb);color:var(--ink);border:0;border-radius:10px;padding:10px;cursor:pointer}.dc button:hover{background:#C3D8EA}
.hb .wrap{display:grid;grid-template-columns:.8fr 1.2fr;gap:50px;align-items:start}
.hrs{background:#fff;border:1px solid var(--ln);border-radius:16px;padding:10px 22px}.hrs table{width:100%;border-collapse:collapse}.hrs td{padding:11px 0;border-bottom:1px solid var(--ln)}.hrs tr:last-child td{border-bottom:0}.hrs td:last-child{text-align:right}
.hrs tr.today td{font-weight:700;color:var(--pn)}
form{background:#fff;border:1px solid var(--ln);border-radius:16px;padding:28px}.fr{display:grid;grid-template-columns:1fr 1fr;gap:14px}.fr>div{min-width:0}
label{display:block;font-weight:700;font-size:15px;margin-bottom:6px}input,select,textarea{width:100%;font:16px var(--b);padding:12px;border:1px solid #BFC7C2;border-radius:10px;margin-bottom:14px;color:var(--ink);background:#fff}
.btn{display:inline-block;background:var(--pn);color:#fff;text-decoration:none;font:700 16px var(--b);padding:14px 24px;border-radius:10px;border:0;cursor:pointer}
.msg{visibility:hidden;margin:12px 0 0;padding:12px 14px;border-radius:10px;background:#E4F2EA;color:var(--pn);font-weight:700}.msg.on{visibility:visible}
.note{font-size:14px;color:var(--gr)}
footer{background:var(--pn);color:#D4E6DE;padding:34px 0;font-size:15px}footer .wrap{display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px}
@media (max-width:980px){.hero .wrap,.hb .wrap{grid-template-columns:1fr}.docs{grid-template-columns:repeat(2,minmax(0,1fr))}.sv{grid-template-columns:1fr 1fr}}
@media (max-width:760px){.burger{display:block}.menu{display:none;position:absolute;top:80px;left:0;right:0;background:#fff;flex-direction:column;padding:18px 22px;z-index:30;border-bottom:1px solid var(--ln)}.menu.open{display:flex}.quick{grid-template-columns:1fr}.sv{grid-template-columns:1fr}.fr{grid-template-columns:1fr}}
@media (max-width:460px){.docs{grid-template-columns:1fr}}
@media (prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}

javascript:
(()=>{const $=id=>document.getElementById(id);const U=i=>`https://images.unsplash.com/photo-${i}?w=500&q=75&auto=format&fit=crop`;
const H=[["Monday",8,19],["Tuesday",8,19],["Wednesday",8,19],["Thursday",8,19],["Friday",8,17],["Saturday",9,13],["Sunday",0,0]];
const f=h=>h===12?'12pm':h>12?(h-12)+'pm':h+'am';const n=new Date(),di=(n.getDay()+6)%7,hr=n.getHours()+n.getMinutes()/60,t=H[di];
$('hrs').innerHTML=H.map((h,i)=>`<tr class="${i===di?'today':''}"><td>${h[0]}${i===di?' (today)':''}</td><td>${h[1]?f(h[1])+' to '+f(h[2]):'Closed'}</td></tr>`).join('');
const open=t[1]&&hr>=t[1]&&hr<t[2];$('dot').classList.toggle('cl',!open);$('now').textContent=open?'Open now':'Closed now';
let nx='';if(open)nx=`Open until ${f(t[2])} today. Call for same-day visits.`;else{for(let k=0;k<7;k++){const j=(di+k)%7,h=H[j];if(h[1]&&(k>0||hr<h[1])){nx=`We open ${k===0?'today':k===1?'tomorrow':h[0]} at ${f(h[1])}.`;break}}}$('nowd').textContent=nx;
const D=[["Dr. Hannah Ortiz","Family medicine","Sees adults and teens. Special interest in diabetes and heart health.","1559839734-2b71ea197ec2","Female doctor in a white coat standing outdoors"],["Dr. Samuel Reyes","Family medicine","12 years at Parkside. Speaks English and Spanish.","1612349317150-e413f6a5b16d","Male doctor with glasses and a stethoscope"],["Dr. Aaron Blake","Women's health","Pregnancy care, contraception and menopause clinics on Tuesdays.","1537368910025-700350fe46c7","Young male doctor in a white coat"],["Jordan Pike, NP","Children","Nurse practitioner for babies and kids. Runs the Saturday walk-in clinic.","1622253692010-333f2da6031d","Smiling nurse practitioner in blue scrubs"]];
let sp='all';function docs(){$('docs').innerHTML=D.filter(d=>sp==='all'||d[1]===sp).map(d=>`<article class="dc"><img src="${U(d[3])}" alt="${d[4]}" width="500" height="500" loading="lazy"><div class="c"><h3>${d[0]}</h3><span class="sp">${d[1]}</span><p>${d[2]}</p><button type="button" data-d="${d[0]}">Book with ${d[0].split(' ').slice(0,2).join(' ').replace(',','')}</button></div></article>`).join('')}
$('chips').onclick=e=>{const b=e.target.closest('button');if(!b)return;$('chips').querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',x===b));sp=b.dataset.s;docs()};docs();
$('bdoc').innerHTML='<option>First available doctor</option>'+D.map(d=>`<option>${d[0]}</option>`).join('');
$('docs').onclick=e=>{const b=e.target.closest('button');if(!b)return;$('bdoc').value=b.dataset.d;$('book').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});setTimeout(()=>$('bn').focus({preventScroll:true}),500)};
const nd=new Date(Date.now()+864e5);$('bd').value=nd.toISOString().slice(0,10);$('bd').min=new Date().toISOString().slice(0,10);
$('bf').onsubmit=e=>{e.preventDefault();const m=$('msg');m.textContent=`Thank you. We've got your request to see ${$('bdoc').value} on ${$('bd').value}. We'll call to confirm the exact time.`;m.classList.add('on')};
})();
(()=>{const b=document.querySelector('.burger'),m=document.getElementById('menu'),y=document.getElementById('yr');
if(b&&m){b.addEventListener('click',()=>{const o=m.classList.toggle('open');b.setAttribute('aria-expanded',o)});
m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded',false)}))}
if(y)y.textContent=new Date().getFullYear()})();
